import 'dotenv/config';
import express from 'express';
import cors from 'cors';
import { loginDiscordBot, getDiscordClient, getGuildId } from './utils/discord';
import { logger } from './utils/logger';
import { authMiddleware } from './middleware/auth';
import { errorHandler, notFoundHandler } from './middleware/errorHandler';
import { startKeepAlive } from './utils/keepalive';

// APIエンドポイント
import { syncRoles } from './api/rolesSync';
import { syncAllRoles } from './api/rolesSyncAll';
import { getNickname, updateNickname } from './api/nickname';
import { createGeneration } from './api/generation';
import { getMemberStatus } from './api/memberStatus';
import { getAllMembers } from './api/members';
import { assignRole, removeRole, listDiscordRoles } from './api/roles';

const app = express();
const PORT = process.env.PORT || 3000;

// CORS設定
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',')
    : '*', // 本番環境では具体的なオリジンを指定することを推奨
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // プリフライトリクエストのキャッシュ時間（24時間）
};

// ミドルウェア
app.use(cors(corsOptions));
app.use(express.json());

// ヘルスチェック（認証不要）
app.get('/health', async (req, res) => {
  try {
    const client = getDiscordClient();
    const wsStatus = client.ws.status;
    const guildId = getGuildId();
    let guildOk = false;
    let guildError = '';
    try {
      const guild = await client.guilds.fetch(guildId);
      guildOk = !!guild;
    } catch (e: any) {
      guildError = e.message || 'Unknown error';
    }
    res.json({
      status: guildOk ? 'ok' : 'degraded',
      timestamp: new Date().toISOString(),
      discord: {
        ws_status: wsStatus,
        bot_user: client.user?.tag || null,
        guild_id: guildId,
        guild_accessible: guildOk,
        guild_error: guildError || undefined,
      },
    });
  } catch (e) {
    res.json({ status: 'ok', timestamp: new Date().toISOString(), discord: { error: 'Client not initialized' } });
  }
});

// 認証が必要なエンドポイント
app.post('/api/roles/sync', authMiddleware, syncRoles);
app.post('/api/roles/sync-all', authMiddleware, syncAllRoles);
app.post('/api/roles/assign', authMiddleware, assignRole);
app.post('/api/roles/remove', authMiddleware, removeRole);
app.get('/api/roles/discord-list', authMiddleware, listDiscordRoles);
app.get('/api/nickname', authMiddleware, getNickname);
app.post('/api/nickname/update', authMiddleware, updateNickname);
app.post('/api/generation', authMiddleware, createGeneration);
app.get('/api/member/status', authMiddleware, getMemberStatus);
app.get('/api/members', authMiddleware, getAllMembers);

// 404ハンドラー
app.use(notFoundHandler);

// エラーハンドラー
app.use(errorHandler);

// サーバー起動
const startServer = async () => {
  try {
    // Discord Botをログイン
    const discordToken = process.env.DISCORD_TOKEN;
    if (!discordToken) {
      throw new Error('DISCORD_TOKEN is not set in environment variables');
    }

    logger.info('Logging in Discord Bot...');
    await loginDiscordBot(discordToken);

    // Supabaseキープアライブを開始
    startKeepAlive();

    // Expressサーバーを起動
    app.listen(PORT, () => {
      logger.info(`🚀 Server is running on port ${PORT}`);
      logger.info(`API endpoints are ready`);
    });
  } catch (error) {
    logger.error('Failed to start server', error);
    process.exit(1);
  }
};

startServer();

import { Request, Response, NextFunction } from 'express';
import { logger } from '../utils/logger';

// Bearer Token認証ミドルウェア
export const authMiddleware = (req: Request, res: Response, next: NextFunction): void => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ 
      success: false, 
      error: 'Unauthorized: Bearer token required' 
    });
    return;
  }

  const token = authHeader.substring(7); // "Bearer "を除去

  // 環境変数からAPIトークンを取得
  const validToken = process.env.API_AUTH_TOKEN;

  if (!validToken) {
    logger.error('API_AUTH_TOKEN is not set in environment variables');
    res.status(500).json({ 
      success: false, 
      error: 'Server configuration error' 
    });
    return;
  }

  if (token !== validToken) {
    logger.warn(`Invalid token attempt from ${req.ip}`);
    res.status(401).json({ 
      success: false, 
      error: 'Unauthorized: Invalid token' 
    });
    return;
  }

  next();
};

import { Request, Response, NextFunction } from 'express';
import { logger } from '../utils/logger';

// エラーハンドリングミドルウェア
export const errorHandler = (
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  logger.error('Unhandled error:', err);

  res.status(500).json({
    success: false,
    error: 'Internal server error',
    details: process.env.NODE_ENV !== 'production' ? err.message : undefined,
  });
};

// 404ハンドラー
export const notFoundHandler = (req: Request, res: Response): void => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
  });
};

import { Client, GatewayIntentBits, GuildMember, Role } from 'discord.js';
import { logger } from './logger';

let client: Client | null = null;

export const initializeDiscordClient = (): Client => {
  if (client) {
    return client;
  }

  client = new Client({
    intents: [
      GatewayIntentBits.Guilds,
      GatewayIntentBits.GuildMembers,
    ],
  });

  client.once('ready', () => {
    logger.info(`✅ Discord Bot is online! Logged in as ${client?.user?.tag}`);
  });

  return client;
};

export const getDiscordClient = (): Client => {
  if (!client) {
    throw new Error('Discord client is not initialized');
  }
  return client;
};

export const loginDiscordBot = async (token: string): Promise<void> => {
  const discordClient = initializeDiscordClient();
  await discordClient.login(token);
};

// Discord ギルド（サーバー）IDを環境変数から取得
export const getGuildId = (): string => {
  const guildId = process.env.DISCORD_GUILD_ID;
  if (!guildId) {
    throw new Error('DISCORD_GUILD_ID is not set in environment variables');
  }
  return guildId;
};

// メンバーを取得
export const getMember = async (discordUid: string): Promise<GuildMember | null> => {
  try {
    const client = getDiscordClient();
    const guildId = getGuildId();
    const guild = await client.guilds.fetch(guildId);
    const member = await guild.members.fetch(discordUid);
    return member;
  } catch (error) {
    logger.error('Failed to fetch Discord member', error);
    return null;
  }
};

// ロールを取得
export const getRole = async (roleId: string): Promise<Role | null> => {
  try {
    const client = getDiscordClient();
    const guildId = getGuildId();
    const guild = await client.guilds.fetch(guildId);
    const role = await guild.roles.fetch(roleId);
    return role;
  } catch (error) {
    logger.error('Failed to fetch Discord role', error);
    return null;
  }
};

// ロールを作成
export const createRole = async (name: string): Promise<Role | null> => {
  try {
    const client = getDiscordClient();
    const guildId = getGuildId();
    const guild = await client.guilds.fetch(guildId);
    const role = await guild.roles.create({ name });
    logger.info(`Created role: ${name} (${role.id})`);
    return role;
  } catch (error) {
    logger.error('Failed to create Discord role', error);
    return null;
  }
};

// メンバーにロールを付与
export const addRoleToMember = async (
  member: GuildMember,
  roleId: string
): Promise<boolean> => {
  try {
    await member.roles.add(roleId);
    logger.info(`Added role ${roleId} to member ${member.user.tag}`);
    return true;
  } catch (error) {
    logger.error('Failed to add role to member', error);
    return false;
  }
};

// メンバーからロールを削除
export const removeRoleFromMember = async (
  member: GuildMember,
  roleId: string
): Promise<boolean> => {
  try {
    await member.roles.remove(roleId);
    logger.info(`Removed role ${roleId} from member ${member.user.tag}`);
    return true;
  } catch (error) {
    logger.error('Failed to remove role from member', error);
    return false;
  }
};

// ニックネームを設定
export const setNickname = async (
  member: GuildMember,
  nickname: string
): Promise<boolean> => {
  try {
    await member.setNickname(nickname);
    logger.info(`Set nickname for ${member.user.tag} to: ${nickname}`);
    return true;
  } catch (error) {
    logger.error('Failed to set nickname', error);
    return false;
  }
};

// Discord上の全ロールを取得
export const getAllDiscordRoles = async () => {
  try {
    const client = getDiscordClient();
    const guildId = getGuildId();
    const guild = await client.guilds.fetch(guildId);
    const roles = await guild.roles.fetch();

    return roles
      .filter(role => role.name !== '@everyone')
      .map(role => ({
        id: role.id,
        name: role.name,
        color: role.hexColor,
        position: role.position,
      }))
      .sort((a, b) => b.position - a.position);
  } catch (error) {
    logger.error('Failed to fetch Discord roles', error);
    return null;
  }
};

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseKey) {
  throw new Error('Supabase URL or Key is missing in environment variables');
}

export const supabase = createClient(supabaseUrl, supabaseKey, {
  db: {
    schema: 'member'
  }
});

import { Request, Response } from 'express';
import { supabase } from '../utils/supabase';
import { getMember, addRoleToMember, removeRoleFromMember } from '../utils/discord';
import { logger } from '../utils/logger';
import { RolesSyncRequest, RolesSyncResponse } from '../types/api';
import { Member, GenerationRole, Team, MemberTeamRelation, TeamLeader } from '../types/database';

export const syncRoles = async (req: Request, res: Response): Promise<void> => {
  try {
    const { discord_uid } = req.body as RolesSyncRequest;

    if (!discord_uid) {
      res.status(400).json({ success: false, error: 'discord_uid is required' });
      return;
    }

    // Discordメンバーを取得
    const member = await getMember(discord_uid);
    if (!member) {
      res.status(404).json({ success: false, error: 'Discord member not found' });
      return;
    }

    // DBから部員情報を取得
    const { data: memberData, error: memberError } = await supabase
      .from('members')
      .select('*')
      .eq('discord_uid', discord_uid)
      .single<Member>();

    if (memberError || !memberData) {
      logger.error('Failed to fetch member from DB', memberError);
      res.status(404).json({ success: false, error: 'Member not found in database' });
      return;
    }

    const rolesAssigned: string[] = [];
    const rolesRemoved: string[] = [];

    // 1. 期生ロールの同期
    const { data: generationRole } = await supabase
      .from('generation_roles')
      .select('*')
      .eq('generation', memberData.generation)
      .single<GenerationRole>();

    if (generationRole) {
      // 期生ロールを付与
      const hasRole = member.roles.cache.has(generationRole.discord_role_id);
      if (!hasRole) {
        await addRoleToMember(member, generationRole.discord_role_id);
        rolesAssigned.push(`${memberData.generation}期生`);
      }

      // 他の期生ロールを削除
      const { data: allGenerationRoles } = await supabase
        .from('generation_roles')
        .select('*')
        .neq('generation', memberData.generation);

      if (allGenerationRoles) {
        for (const otherGenRole of allGenerationRoles) {
          if (member.roles.cache.has(otherGenRole.discord_role_id)) {
            await removeRoleFromMember(member, otherGenRole.discord_role_id);
            rolesRemoved.push(`${otherGenRole.generation}期生`);
          }
        }
      }
    }

    // 2. 班ロールの同期
    // メンバーが所属する班を取得
    const { data: memberTeams } = await supabase
      .from('member_team_relations')
      .select('team_id')
      .eq('member_id', memberData.supabase_auth_user_id);

    const teamIds = memberTeams?.map((mt: { team_id: string }) => mt.team_id) || [];

    // 所属班のロールを取得
    const { data: teams } = await supabase
      .from('teams')
      .select('*')
      .in('id', teamIds);

    const teamRoleIds = teams?.map((t: Team) => t.discord_role_id) || [];

    // 所属班のロールを付与
    for (const team of teams || []) {
      if (!member.roles.cache.has(team.discord_role_id)) {
        await addRoleToMember(member, team.discord_role_id);
        rolesAssigned.push(team.name);
      }
    }

    // 全ての班を取得
    const { data: allTeams } = await supabase.from('teams').select('*');

    // 所属していない班のロールを削除
    for (const team of allTeams || []) {
      if (
        !teamRoleIds.includes(team.discord_role_id) &&
        member.roles.cache.has(team.discord_role_id)
      ) {
        await removeRoleFromMember(member, team.discord_role_id);
        rolesRemoved.push(team.name);
      }
    }

    // 3. 班長ロールの同期
    const leaderRoleId = process.env.DISCORD_LEADER_ROLE_ID;
    if (leaderRoleId) {
      const { data: isLeader } = await supabase
        .from('team_leaders')
        .select('*')
        .eq('member_id', memberData.supabase_auth_user_id)
        .single<TeamLeader>();

      if (isLeader) {
        // 班長ロールを付与
        if (!member.roles.cache.has(leaderRoleId)) {
          await addRoleToMember(member, leaderRoleId);
          rolesAssigned.push('班長');
        }
      } else {
        // 班長ロールを削除
        if (member.roles.cache.has(leaderRoleId)) {
          await removeRoleFromMember(member, leaderRoleId);
          rolesRemoved.push('班長');
        }
      }
    }

    // 4. Status別ロールの同期（中学生/高校生/OB）
    const jhRoleId = process.env.DISCORD_JH_ROLE_ID;
    const hRoleId = process.env.DISCORD_H_ROLE_ID;
    const obRoleId = process.env.DISCORD_OB_ROLE_ID;
    const statusRoleIds = [jhRoleId, hRoleId, obRoleId].filter(Boolean) as string[];

    // 現在のstatusに応じたロールを決定
    let targetStatusRoleId: string | null = null;
    let statusRoleName = '';

    if (memberData.status === 0 && jhRoleId) {
      targetStatusRoleId = jhRoleId;
      statusRoleName = '中学生';
    } else if (memberData.status === 1 && hRoleId) {
      targetStatusRoleId = hRoleId;
      statusRoleName = '高校生';
    } else if (memberData.status === 2 && obRoleId) {
      targetStatusRoleId = obRoleId;
      statusRoleName = 'OB';
    }

    // 正しいstatusロールを付与
    if (targetStatusRoleId) {
      if (!member.roles.cache.has(targetStatusRoleId)) {
        await addRoleToMember(member, targetStatusRoleId);
        rolesAssigned.push(statusRoleName);
      }
    }

    // 他のstatusロールを削除
    for (const roleId of statusRoleIds) {
      if (roleId !== targetStatusRoleId && member.roles.cache.has(roleId)) {
        await removeRoleFromMember(member, roleId);
        const removedName = roleId === jhRoleId ? '中学生' : roleId === hRoleId ? '高校生' : 'OB';
        rolesRemoved.push(removedName);
      }
    }

    // 5. 部員ロール（MEMBERロール）の同期
    const memberRoleId = process.env.DISCORD_MEMBER_ROLE_ID;
    if (memberRoleId) {
      // status 0 or 1（中学生・高校生）の場合のみ付与
      if (memberData.status === 0 || memberData.status === 1) {
        if (!member.roles.cache.has(memberRoleId)) {
          await addRoleToMember(member, memberRoleId);
          rolesAssigned.push('部員');
        }
      } else {
        // status 2（OB）の場合は削除
        if (member.roles.cache.has(memberRoleId)) {
          await removeRoleFromMember(member, memberRoleId);
          rolesRemoved.push('部員');
        }
      }
    }

    // 6. 認証済みロール（VERIFIEDロール）の付与
    const verifiedRoleId = process.env.DISCORD_VERIFIED_ROLE_ID;
    if (verifiedRoleId) {
      // DBに登録されていれば付与
      if (!member.roles.cache.has(verifiedRoleId)) {
        await addRoleToMember(member, verifiedRoleId);
        rolesAssigned.push('認証済み');
      }
    }

    const response: RolesSyncResponse = {
      success: true,
      roles_assigned: rolesAssigned,
      roles_removed: rolesRemoved,
    };

    logger.info(`Roles synced for ${discord_uid}`, response);
    res.json(response);
  } catch (error) {
    logger.error('Error in syncRoles', error);
    res.status(500).json({ success: false, error: 'Internal server error' });
  }
};

import { Request, Response } from 'express';
import { supabase } from '../utils/supabase';
import { getMember, addRoleToMember, removeRoleFromMember } from '../utils/discord';
import { logger } from '../utils/logger';
import { Member, GenerationRole, Team, MemberTeamRelation, TeamLeader } from '../types/database';

/**
 * 全メンバーのロールを一括同期
 * POST /api/roles/sync-all
 */
export const syncAllRoles = async (req: Request, res: Response): Promise<void> => {
  try {
    logger.info('Starting sync for all members...');

    // DBから全メンバーを取得（削除されていないメンバーのみ）
    const { data: members, error: membersError } = await supabase
      .from('members')
      .select('*')
      .is('deleted_at', null);

    if (membersError || !members) {
      logger.error('Failed to fetch members from DB', membersError);
      res.status(500).json({ success: false, error: 'Failed to fetch members from database' });
      return;
    }

    if (members.length === 0) {
      logger.info('No members found in database');
      res.json({ success: true, message: 'No members to sync', synced: 0, failed: 0 });
      return;
    }

    const results = {
      synced: 0,
      failed: 0,
      errors: [] as { discord_uid: string; error: string }[],
    };

    // 各メンバーのロールを同期
    for (const memberData of members as Member[]) {
      try {
        logger.info(`Syncing roles for member: ${memberData.discord_uid}`);

        // Discordメンバーを取得
        const member = await getMember(memberData.discord_uid);
        if (!member) {
          logger.warn(`Discord member not found: ${memberData.discord_uid}`);
          results.failed++;
          results.errors.push({
            discord_uid: memberData.discord_uid,
            error: 'Discord member not found',
          });
          continue;
        }

        const rolesAssigned: string[] = [];
        const rolesRemoved: string[] = [];

        // 1. 期生ロールの同期
        const { data: generationRole } = await supabase
          .from('generation_roles')
          .select('*')
          .eq('generation', memberData.generation)
          .single<GenerationRole>();

        if (generationRole) {
          const hasRole = member.roles.cache.has(generationRole.discord_role_id);
          if (!hasRole) {
            await addRoleToMember(member, generationRole.discord_role_id);
            rolesAssigned.push(generationRole.discord_role_id);
            logger.info(`Added generation role to ${memberData.discord_uid}`);
          }
        }

        // 2. 班ロールの同期
        const { data: memberTeams } = await supabase
          .from('member_team_relations')
          .select('team_id')
          .eq('member_id', memberData.supabase_auth_user_id);

        if (memberTeams && memberTeams.length > 0) {
          const teamIds = memberTeams.map((mt: any) => mt.team_id);
          const { data: teams } = await supabase
            .from('teams')
            .select('*')
            .in('id', teamIds);

          if (teams) {
            for (const team of teams as Team[]) {
              const hasRole = member.roles.cache.has(team.discord_role_id);
              if (!hasRole) {
                await addRoleToMember(member, team.discord_role_id);
                rolesAssigned.push(team.discord_role_id);
                logger.info(`Added team role ${team.name} to ${memberData.discord_uid}`);
              }
            }
          }
        }

        // 3. 班長ロールの同期
        const leaderRoleId = process.env.DISCORD_LEADER_ROLE_ID;
        if (leaderRoleId) {
          const { data: isLeader } = await supabase
            .from('team_leaders')
            .select('*')
            .eq('member_id', memberData.supabase_auth_user_id)
            .single<TeamLeader>();

          const hasLeaderRole = member.roles.cache.has(leaderRoleId);

          if (isLeader && !hasLeaderRole) {
            await addRoleToMember(member, leaderRoleId);
            rolesAssigned.push(leaderRoleId);
            logger.info(`Added leader role to ${memberData.discord_uid}`);
          } else if (!isLeader && hasLeaderRole) {
            await removeRoleFromMember(member, leaderRoleId);
            rolesRemoved.push(leaderRoleId);
            logger.info(`Removed leader role from ${memberData.discord_uid}`);
          }
        }

        // 4. ステータス別ロールの同期（中学生/高校生/OB）
        const jhRoleId = process.env.DISCORD_JH_ROLE_ID;
        const hRoleId = process.env.DISCORD_H_ROLE_ID;
        const obRoleId = process.env.DISCORD_OB_ROLE_ID;

        logger.info(`Member ${memberData.discord_uid} status: ${memberData.status}`);

        // 新しいステータスロールを決定
        let targetStatusRoleId: string | undefined;
        if (memberData.status === 0 && jhRoleId) {
          targetStatusRoleId = jhRoleId;
          logger.info(`Target status role: JH (${jhRoleId})`);
        } else if (memberData.status === 1 && hRoleId) {
          targetStatusRoleId = hRoleId;
          logger.info(`Target status role: H (${hRoleId})`);
        } else if (memberData.status === 2 && obRoleId) {
          targetStatusRoleId = obRoleId;
          logger.info(`Target status role: OB (${obRoleId})`);
        }

        // 不要なステータスロールを削除
        if (jhRoleId && member.roles.cache.has(jhRoleId) && targetStatusRoleId !== jhRoleId) {
          await removeRoleFromMember(member, jhRoleId);
          rolesRemoved.push(jhRoleId);
          logger.info(`Removed JH role from ${memberData.discord_uid}`);
        }
        if (hRoleId && member.roles.cache.has(hRoleId) && targetStatusRoleId !== hRoleId) {
          await removeRoleFromMember(member, hRoleId);
          rolesRemoved.push(hRoleId);
          logger.info(`Removed H role from ${memberData.discord_uid}`);
        }
        if (obRoleId && member.roles.cache.has(obRoleId) && targetStatusRoleId !== obRoleId) {
          await removeRoleFromMember(member, obRoleId);
          rolesRemoved.push(obRoleId);
          logger.info(`Removed OB role from ${memberData.discord_uid}`);
        }

        // 必要なステータスロールを付与
        if (targetStatusRoleId && !member.roles.cache.has(targetStatusRoleId)) {
          await addRoleToMember(member, targetStatusRoleId);
          rolesAssigned.push(targetStatusRoleId);
          logger.info(`Added status role ${targetStatusRoleId} to ${memberData.discord_uid}`);
        } else if (targetStatusRoleId) {
          logger.info(`Member ${memberData.discord_uid} already has correct status role ${targetStatusRoleId}`);
        }

        // 5. 部員ロールの同期（中学生・高校生のみ）
        const memberRoleId = process.env.DISCORD_MEMBER_ROLE_ID;
        if (memberRoleId && (memberData.status === 0 || memberData.status === 1)) {
          const hasMemberRole = member.roles.cache.has(memberRoleId);
          if (!hasMemberRole) {
            await addRoleToMember(member, memberRoleId);
            rolesAssigned.push(memberRoleId);
            logger.info(`Added member role to ${memberData.discord_uid}`);
          }
        } else if (memberRoleId && memberData.status === 2) {
          // OBの場合は部員ロールを削除
          const hasMemberRole = member.roles.cache.has(memberRoleId);
          if (hasMemberRole) {
            await removeRoleFromMember(member, memberRoleId);
            rolesRemoved.push(memberRoleId);
            logger.info(`Removed member role from ${memberData.discord_uid}`);
          }
        }

        // 6. 認証済みロールの同期
        const verifiedRoleId = process.env.DISCORD_VERIFIED_ROLE_ID;
        if (verifiedRoleId) {
          const hasVerifiedRole = member.roles.cache.has(verifiedRoleId);
          if (!hasVerifiedRole) {
            await addRoleToMember(member, verifiedRoleId);
            rolesAssigned.push(verifiedRoleId);
            logger.info(`Added verified role to ${memberData.discord_uid}`);
          }
        }

        logger.info(
          `Successfully synced roles for ${memberData.discord_uid} - Assigned: ${rolesAssigned.length}, Removed: ${rolesRemoved.length}`
        );
        results.synced++;
      } catch (error) {
        logger.error(`Failed to sync roles for ${memberData.discord_uid}`, error);
        results.failed++;
        results.errors.push({
          discord_uid: memberData.discord_uid,
          error: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    }

    logger.info(
      `Sync completed - Synced: ${results.synced}, Failed: ${results.failed}`
    );

    res.json({
      success: true,
      synced: results.synced,
      failed: results.failed,
      total: members.length,
      errors: results.errors.length > 0 ? results.errors : undefined,
    });
  } catch (error) {
    logger.error('Error in syncAllRoles', error);
    res.status(500).json({
      success: false,
      error: 'Internal server error',
    });
  }
};

import { Request, Response } from 'express';
import { supabase } from '../utils/supabase';
