export const startKeepAlive = () => {
  const INTERVAL = 6 * 60 * 60 * 1000; // 6時間ごと（ミリ秒）

  // 初回実行
  performKeepAlive();

  // 定期実行
  setInterval(() => {
    performKeepAlive();
  }, INTERVAL);

  logger.info(`✅ Supabase keep-alive started (interval: ${INTERVAL / 1000 / 60 / 60} hours)`);
};

